// Package payments charges invoices through the payment gateway.
package payments

import (
	"context"
	"errors"
	"fmt"

	"example.com/tally/internal/billing"
	"example.com/tally/internal/clock"
	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
)

// ChargeRequest asks the gateway to take money from a payment method.
type ChargeRequest struct {
	Amount        int64 // minor units
	Currency      money.Currency
	PaymentMethod string // "pm_..."
	Description   string
}

// ChargeResult is a successful charge.
type ChargeResult struct {
	Ref string // the gateway's reference, "ch_..."
}

// Gateway is the payment processor.
type Gateway interface {
	Charge(ctx context.Context, req ChargeRequest) (ChargeResult, error)
}

// DeclineError is a charge the card's issuer refused. Nothing was taken.
type DeclineError struct {
	Code string // for example "card_declined", "insufficient_funds"
}

func (e *DeclineError) Error() string { return "card declined: " + e.Code }

// Errors.
var (
	// ErrUnavailable means the gateway could not be reached or failed; nothing was taken and the charge may be retried.
	ErrUnavailable     = errors.New("payment gateway unavailable")
	ErrAlreadyPaid     = errors.New("the invoice is already paid")
	ErrInvoiceVoid     = errors.New("the invoice is void")
	ErrNoPaymentMethod = errors.New("no payment method to charge")
)

// Publisher sends events to the organization's webhook endpoints (webhooks.Service).
type Publisher interface {
	Publish(ctx context.Context, orgID, eventType string, data any) error
}

// Service pays invoices.
type Service struct {
	Store     *store.Store
	Gateway   Gateway
	Clock     clock.Clock
	Publisher Publisher // nil: no events
}

// Pay charges an open invoice's total to paymentMethod, or to the customer's default payment method when it is empty, and
// marks the invoice paid. An invoice whose total is zero or less is marked paid without a charge. A declined charge is
// recorded as a failed payment and returned as a *DeclineError; when the gateway is unavailable nothing is recorded and the
// error wraps ErrUnavailable.
func (s *Service) Pay(ctx context.Context, orgID, invoiceID, paymentMethod string) (store.Invoice, store.Payment, error) {
	inv, ok := s.Store.Invoice(orgID, invoiceID)
	if !ok {
		return store.Invoice{}, store.Payment{}, store.ErrNotFound
	}
	switch inv.Status {
	case store.InvoicePaid:
		return inv, store.Payment{}, ErrAlreadyPaid
	case store.InvoiceVoid:
		return inv, store.Payment{}, ErrInvoiceVoid
	}
	total := billing.Compute(inv).Total
	if total <= 0 {
		inv, err := s.markPaid(ctx, inv, store.Payment{})
		return inv, store.Payment{}, err
	}
	if paymentMethod == "" {
		if c, ok := s.Store.Customer(orgID, inv.CustomerID); ok {
			paymentMethod = c.DefaultPaymentMethod
		}
	}
	if paymentMethod == "" {
		return inv, store.Payment{}, ErrNoPaymentMethod
	}
	res, err := s.Gateway.Charge(ctx, ChargeRequest{Amount: total, Currency: inv.Currency, PaymentMethod: paymentMethod, Description: "Invoice " + inv.ID})
	var decline *DeclineError
	switch {
	case errors.As(err, &decline):
		p, perr := s.Store.CreatePayment(store.Payment{OrgID: orgID, InvoiceID: inv.ID, Amount: total, Currency: inv.Currency, Status: store.PaymentFailed, FailureCode: decline.Code}, s.Clock.Now())
		if perr != nil {
			return inv, store.Payment{}, perr
		}
		s.publish(ctx, orgID, "invoice.payment_failed", map[string]any{"invoice_id": inv.ID, "payment_id": p.ID, "failure_code": decline.Code})
		return inv, p, err
	case err != nil:
		if errors.Is(err, ErrUnavailable) {
			return inv, store.Payment{}, err
		}
		return inv, store.Payment{}, fmt.Errorf("%w: %v", ErrUnavailable, err)
	}
	p, err := s.Store.CreatePayment(store.Payment{OrgID: orgID, InvoiceID: inv.ID, Amount: total, Currency: inv.Currency, Status: store.PaymentSucceeded, GatewayRef: res.Ref}, s.Clock.Now())
	if err != nil {
		return inv, store.Payment{}, err
	}
	inv, err = s.markPaid(ctx, inv, p)
	return inv, p, err
}

func (s *Service) markPaid(ctx context.Context, inv store.Invoice, p store.Payment) (store.Invoice, error) {
	now := s.Clock.Now()
	inv, err := s.Store.UpdateInvoice(inv.OrgID, inv.ID, func(i *store.Invoice) error {
		i.Status = store.InvoicePaid
		i.PaidAt = &now
		return nil
	})
	if err != nil {
		return store.Invoice{}, err
	}
	s.publish(ctx, inv.OrgID, "invoice.paid", map[string]any{"invoice_id": inv.ID, "payment_id": p.ID, "amount": p.Amount, "currency": inv.Currency})
	return inv, nil
}

func (s *Service) publish(ctx context.Context, orgID, typ string, data any) {
	if s.Publisher != nil {
		_ = s.Publisher.Publish(ctx, orgID, typ, data)
	}
}
package payments

import (
	"context"
	"fmt"
	"strings"
	"sync"
)

// Fake is the gateway of tests and the demo server. What it does depends on the payment method:
//
//	pm_card_declined            declined, code "card_declined"
//	pm_card_insufficient_funds  declined, code "insufficient_funds"
//	pm_gateway_down             fails with ErrUnavailable
//	any other "pm_..."          succeeds
//	anything else               declined, code "invalid_payment_method"
//
// Like the real gateway in its default mode, it takes every charge it is asked for: it does not merge repeated requests.
type Fake struct {
	// OnCharge, when set, is called at the start of every Charge, before its outcome is decided. Tests use it to hold a
	// charge while they do something else. Set it before the fake is used.
	OnCharge func(ChargeRequest)

	mu      sync.Mutex
	calls   []ChargeRequest
	charges []Charge
}

// Charge is a charge the fake took.
type Charge struct {
	Ref string
	ChargeRequest
}

// Charge implements Gateway.
func (f *Fake) Charge(ctx context.Context, req ChargeRequest) (ChargeResult, error) {
	if f.OnCharge != nil {
		f.OnCharge(req)
	}
	if err := ctx.Err(); err != nil {
		return ChargeResult{}, fmt.Errorf("%w: %v", ErrUnavailable, err)
	}
	f.mu.Lock()
	defer f.mu.Unlock()
	f.calls = append(f.calls, req)
	switch pm := req.PaymentMethod; {
	case pm == "pm_card_declined":
		return ChargeResult{}, &DeclineError{Code: "card_declined"}
	case pm == "pm_card_insufficient_funds":
		return ChargeResult{}, &DeclineError{Code: "insufficient_funds"}
	case pm == "pm_gateway_down":
		return ChargeResult{}, ErrUnavailable
	case !strings.HasPrefix(pm, "pm_"):
		return ChargeResult{}, &DeclineError{Code: "invalid_payment_method"}
	}
	c := Charge{Ref: fmt.Sprintf("ch_%06d", len(f.charges)+1), ChargeRequest: req}
	f.charges = append(f.charges, c)
	return ChargeResult{Ref: c.Ref}, nil
}

// Calls returns every charge request the fake received, including declined and failed ones.
func (f *Fake) Calls() []ChargeRequest {
	f.mu.Lock()
	defer f.mu.Unlock()
	return append([]ChargeRequest(nil), f.calls...)
}

// Charges returns the charges the fake took (the money that moved).
func (f *Fake) Charges() []Charge {
	f.mu.Lock()
	defer f.mu.Unlock()
	return append([]Charge(nil), f.charges...)
}
package subscriptions_test

import (
	"context"
	"testing"
	"time"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
	"example.com/tally/internal/subscriptions"
)

func TestCreateChargesTheFirstPeriod(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_card_visa"; return nil })
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 3})
	if err != nil {
		t.Fatal(err)
	}
	now := e.Clock.Now()
	if sub.Status != store.Active || !sub.CurrentPeriodStart.Equal(now) || !sub.CurrentPeriodEnd.Equal(now.AddDate(0, 1, 0)) {
		t.Fatalf("subscription = %+v", sub)
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 1 || invs[0].Status != store.InvoicePaid || invs[0].Lines[0].Quantity != 3 || invs[0].Lines[0].UnitAmount != 2000 {
		t.Fatalf("invoices = %+v", invs)
	}
	if cs := e.Gateway.Charges(); len(cs) != 1 || cs[0].Amount != 6000 {
		t.Fatalf("charges = %+v", cs)
	}
}

func TestDeclinedFirstChargeIsPastDue(t *testing.T) {
	e := apitest.New(t)
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_card_declined"; return nil })
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	sub, err := e.Subs.Create(context.Background(), e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	if err != nil || sub.Status != store.PastDue {
		t.Fatalf("subscription = %+v, %v", sub, err)
	}
}

func TestTrialThenRenewal(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	p, err := e.Store.CreatePlan(store.Plan{OrgID: e.Acme.ID, Name: "Pro", Currency: money.EUR, UnitAmount: 4900, Interval: store.Monthly, TrialDays: 14}, e.Clock.Now())
	if err != nil {
		t.Fatal(err)
	}
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	trialEnd := e.Clock.Now().AddDate(0, 0, 14)
	if sub.Status != store.Trialing || sub.TrialEnd == nil || !sub.TrialEnd.Equal(trialEnd) || !sub.CurrentPeriodEnd.Equal(trialEnd) {
		t.Fatalf("subscription = %+v", sub)
	}
	if invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{}); len(invs) != 0 {
		t.Fatalf("a trial was invoiced: %+v", invs)
	}
	e.Clock.Set(trialEnd)
	if n, err := e.Subs.RenewDue(ctx); err != nil || n != 1 {
		t.Fatalf("RenewDue = %d, %v", n, err)
	}
	got, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
	if got.Status != store.Active || !got.CurrentPeriodStart.Equal(trialEnd) || !got.CurrentPeriodEnd.Equal(trialEnd.AddDate(0, 1, 0)) {
		t.Fatalf("after the trial = %+v", got)
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 1 || invs[0].Status != store.InvoiceOpen || invs[0].PeriodStart == nil || !invs[0].PeriodStart.Equal(trialEnd) {
		t.Fatalf("invoices = %+v (no payment method: the invoice stays open)", invs)
	}
	if n, _ := e.Subs.RenewDue(ctx); n != 0 {
		t.Fatalf("renewed twice: %d", n)
	}
}

func TestCancelAtPeriodEnd(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	sub, _ := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	sub, err := e.Subs.Cancel(ctx, e.Acme.ID, sub.ID, true)
	if err != nil || sub.Status != store.Active || !sub.CancelAtPeriodEnd {
		t.Fatalf("cancel = %+v, %v", sub, err)
	}
	e.Clock.Set(sub.CurrentPeriodEnd)
	if _, err := e.Subs.RenewDue(ctx); err != nil {
		t.Fatal(err)
	}
	got, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
	if got.Status != store.Canceled || got.CanceledAt == nil || !got.CanceledAt.Equal(sub.CurrentPeriodEnd) {
		t.Fatalf("after the period = %+v", got)
	}
	if invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID}); len(invs) != 1 {
		t.Fatalf("invoices = %d, want only the first", len(invs))
	}
}

func TestMeteredBillsUsageInArrears(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	p, _ := e.Store.CreatePlan(store.Plan{OrgID: e.Acme.ID, Name: "API calls", Currency: money.USD, UnitAmount: 2, Interval: store.Monthly, UsageType: store.Metered}, e.Clock.Now())
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	if invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{}); len(invs) != 0 {
		t.Fatalf("a metered plan was invoiced in advance: %+v", invs)
	}
	start, end := sub.CurrentPeriodStart, sub.CurrentPeriodEnd
	for _, u := range []struct {
		q  int64
		at time.Time
	}{{100, start}, {250, start.Add(48 * time.Hour)}, {7, end}} {
		if _, err := e.Store.AddUsage(e.Acme.ID, sub.ID, u.q, u.at, e.Clock.Now()); err != nil {
			t.Fatal(err)
		}
	}
	e.Clock.Set(end)
	if _, err := e.Subs.RenewDue(ctx); err != nil {
		t.Fatal(err)
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 1 || len(invs[0].Lines) != 1 || invs[0].Lines[0].Quantity != 350 || !invs[0].PeriodEnd.Equal(end) {
		t.Fatalf("invoices = %+v (usage at the period's end belongs to the next period)", invs)
	}
}

