// Prorate returns amount times part over whole, rounded half away from zero to a whole minor unit. It does the arithmetic
// exactly, so the product may exceed an int64; whole must not be zero.
func Prorate(amount, part, whole int64) int64 {
	num := new(big.Int).Mul(big.NewInt(amount), big.NewInt(part))
	den := big.NewInt(whole)
	q, r := new(big.Int).QuoRem(num, den, new(big.Int))
	// QuoRem truncates toward zero; the remainder has the sign of num, so it rounds away from zero when twice its size
	// reaches the divisor's.
	if new(big.Int).Lsh(new(big.Int).Abs(r), 1).Cmp(new(big.Int).Abs(den)) >= 0 {
		q.Add(q, big.NewInt(int64(num.Sign()*den.Sign())))
	}
	return q.Int64()
}

