// UpdateInput changes a subscription; nil fields stay as they are.
type UpdateInput struct {
	PlanID   *string
	Quantity *int
}

// Update changes a subscription's plan or quantity. A subscription's value is its plan's unit amount times its quantity:
//   - An upgrade (the value rises) applies at once and is billed at once: an invoice for the unused part of the current
//     period on the old plan, credited, and one for the rest of the period on the new plan. The current period does not change.
//   - A downgrade (the value falls) does not apply now. It is pending until the next renewal, which bills the new plan and
//     quantity.
//   - A change that keeps the value applies at once and bills nothing, and so does any change to a trialing subscription.
//
// A change replaces any pending downgrade, unless it is itself a downgrade. Fields that are nil keep the subscription's
// pending plan and quantity when it has one, and its current ones otherwise.
func (s *Service) Update(ctx context.Context, orgID, id string, in UpdateInput) (store.Subscription, error) {
	if in.PlanID != nil {
		p, ok := s.Store.Plan(orgID, *in.PlanID)
		if !ok {
			return store.Subscription{}, store.ErrNotFound
		}
		if !p.Active {
			return store.Subscription{}, ErrPlanInactive
		}
	}
	cur, ok := s.Store.Subscription(orgID, id)
	if !ok {
		return store.Subscription{}, store.ErrNotFound
	}
	if cur.Status == store.Canceled {
		return store.Subscription{}, ErrCanceled
	}
	from, ok := s.Store.Plan(orgID, cur.PlanID)
	if !ok {
		return store.Subscription{}, store.ErrNotFound
	}
	planID, qty := cur.PlanID, cur.Quantity
	if cur.PendingPlanID != nil {
		planID, qty = *cur.PendingPlanID, *cur.PendingQuantity
	}
	if in.PlanID != nil {
		planID = *in.PlanID
	}
	if in.Quantity != nil {
		qty = *in.Quantity
	}
	to, ok := s.Store.Plan(orgID, planID)
	if !ok {
		return store.Subscription{}, store.ErrNotFound
	}
	if planID != cur.PlanID || qty != cur.Quantity {
		if err := checkCompatible(from, to); err != nil {
			return store.Subscription{}, err
		}
	}
	oldValue, newValue := from.UnitAmount*int64(cur.Quantity), to.UnitAmount*int64(qty)
	downgrade := newValue < oldValue && cur.Status != store.Trialing
	sub, err := s.Store.UpdateSubscription(orgID, id, func(x *store.Subscription) error {
		// Refuse to apply a change to a subscription that changed since it was read: its billing would be wrong.
		if !reflect.DeepEqual(*x, cur) {
			return store.ErrConflict
		}
		if downgrade {
			x.PendingPlanID, x.PendingQuantity = &planID, &qty
			return nil
		}
		x.PlanID, x.Quantity = planID, qty
		x.PendingPlanID, x.PendingQuantity = nil, nil
		return nil
	})
