package subscriptions_test

import (
	"context"
	"errors"
	"reflect"
	"testing"
	"time"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/billing"
	"example.com/tally/internal/money"
	"example.com/tally/internal/payments"
	"example.com/tally/internal/store"
	"example.com/tally/internal/subscriptions"
)

func TestCreateChargesTheFirstPeriod(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_card_visa"; return nil })
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 3})
	if err != nil {
		t.Fatal(err)
	}
	now := e.Clock.Now()
	if sub.Status != store.Active || !sub.CurrentPeriodStart.Equal(now) || !sub.CurrentPeriodEnd.Equal(now.AddDate(0, 1, 0)) {
		t.Fatalf("subscription = %+v", sub)
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 1 || invs[0].Status != store.InvoicePaid || invs[0].Lines[0].Quantity != 3 || invs[0].Lines[0].UnitAmount != 2000 {
		t.Fatalf("invoices = %+v", invs)
	}
	if cs := e.Gateway.Charges(); len(cs) != 1 || cs[0].Amount != 6000 {
		t.Fatalf("charges = %+v", cs)
	}
}

func TestDeclinedFirstChargeIsPastDue(t *testing.T) {
	e := apitest.New(t)
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_card_declined"; return nil })
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	sub, err := e.Subs.Create(context.Background(), e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	if err != nil || sub.Status != store.PastDue {
		t.Fatalf("subscription = %+v, %v", sub, err)
	}
}

func TestTrialThenRenewal(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	p, err := e.Store.CreatePlan(store.Plan{OrgID: e.Acme.ID, Name: "Pro", Currency: money.EUR, UnitAmount: 4900, Interval: store.Monthly, TrialDays: 14}, e.Clock.Now())
	if err != nil {
		t.Fatal(err)
	}
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	trialEnd := e.Clock.Now().AddDate(0, 0, 14)
	if sub.Status != store.Trialing || sub.TrialEnd == nil || !sub.TrialEnd.Equal(trialEnd) || !sub.CurrentPeriodEnd.Equal(trialEnd) {
		t.Fatalf("subscription = %+v", sub)
	}
	if invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{}); len(invs) != 0 {
		t.Fatalf("a trial was invoiced: %+v", invs)
	}
	e.Clock.Set(trialEnd)
	if n, err := e.Subs.RenewDue(ctx); err != nil || n != 1 {
		t.Fatalf("RenewDue = %d, %v", n, err)
	}
	got, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
	if got.Status != store.Active || !got.CurrentPeriodStart.Equal(trialEnd) || !got.CurrentPeriodEnd.Equal(trialEnd.AddDate(0, 1, 0)) {
		t.Fatalf("after the trial = %+v", got)
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 1 || invs[0].Status != store.InvoiceOpen || invs[0].PeriodStart == nil || !invs[0].PeriodStart.Equal(trialEnd) {
		t.Fatalf("invoices = %+v (no payment method: the invoice stays open)", invs)
	}
	if n, _ := e.Subs.RenewDue(ctx); n != 0 {
		t.Fatalf("renewed twice: %d", n)
	}
}

func TestCancelAtPeriodEnd(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	sub, _ := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	sub, err := e.Subs.Cancel(ctx, e.Acme.ID, sub.ID, true)
	if err != nil || sub.Status != store.Active || !sub.CancelAtPeriodEnd {
		t.Fatalf("cancel = %+v, %v", sub, err)
	}
	e.Clock.Set(sub.CurrentPeriodEnd)
	if _, err := e.Subs.RenewDue(ctx); err != nil {
		t.Fatal(err)
	}
	got, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
	if got.Status != store.Canceled || got.CanceledAt == nil || !got.CanceledAt.Equal(sub.CurrentPeriodEnd) {
		t.Fatalf("after the period = %+v", got)
	}
	if invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID}); len(invs) != 1 {
		t.Fatalf("invoices = %d, want only the first", len(invs))
	}
}

func TestMeteredBillsUsageInArrears(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	p, _ := e.Store.CreatePlan(store.Plan{OrgID: e.Acme.ID, Name: "API calls", Currency: money.USD, UnitAmount: 2, Interval: store.Monthly, UsageType: store.Metered}, e.Clock.Now())
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	if invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{}); len(invs) != 0 {
		t.Fatalf("a metered plan was invoiced in advance: %+v", invs)
	}
	start, end := sub.CurrentPeriodStart, sub.CurrentPeriodEnd
	for _, u := range []struct {
		q  int64
		at time.Time
	}{{100, start}, {250, start.Add(48 * time.Hour)}, {7, end}} {
		if _, err := e.Store.AddUsage(e.Acme.ID, sub.ID, u.q, u.at, e.Clock.Now()); err != nil {
			t.Fatal(err)
		}
	}
	e.Clock.Set(end)
	if _, err := e.Subs.RenewDue(ctx); err != nil {
		t.Fatal(err)
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 1 || len(invs[0].Lines) != 1 || invs[0].Lines[0].Quantity != 350 || !invs[0].PeriodEnd.Equal(end) {
		t.Fatalf("invoices = %+v (usage at the period's end belongs to the next period)", invs)
	}
}

// newPlan adds a plan of Acme's.
func newPlan(t *testing.T, e *apitest.Env, name string, cur money.Currency, amount int64, iv store.Interval, usage store.UsageType, trialDays int) store.Plan {
	t.Helper()
	p, err := e.Store.CreatePlan(store.Plan{OrgID: e.Acme.ID, Name: name, Currency: cur, UnitAmount: amount, Interval: iv, UsageType: usage, TrialDays: trialDays}, e.Clock.Now())
	if err != nil {
		t.Fatal(err)
	}
	return p
}

// subscribe starts a monthly subscription of Acme's customer Jane to plan p, paid by payment method pm.
func subscribe(t *testing.T, e *apitest.Env, p store.Plan, qty int, pm string) store.Subscription {
	t.Helper()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = pm; return nil })
	sub, err := e.Subs.Create(context.Background(), e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: qty})
	if err != nil {
		t.Fatal(err)
	}
	return sub
}

// change applies an update to a subscription of Acme's.
func change(t *testing.T, e *apitest.Env, sub store.Subscription, in subscriptions.UpdateInput) store.Subscription {
	t.Helper()
	got, err := e.Subs.Update(context.Background(), e.Acme.ID, sub.ID, in)
	if err != nil {
		t.Fatal(err)
	}
	return got
}

// invoicesOf returns a subscription's invoices, oldest first.
func invoicesOf(e *apitest.Env, sub store.Subscription) []store.Invoice {
	return e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
}

// afterTenDays moves the clock 10 of the 31 days of a period starting on apitest.Start, leaving 21.
func afterTenDays(e *apitest.Env) {
	e.Clock.Set(e.Clock.Now().AddDate(0, 0, 10))
}

func TestUpgradeBillsTheRemainingTimeAtOnce(t *testing.T) {
	e := apitest.New(t)
	team := newPlan(t, e, "Team", money.USD, 2000, store.Monthly, store.Licensed, 0)
	pro := newPlan(t, e, "Pro", money.USD, 5000, store.Monthly, store.Licensed, 0)
	sub := subscribe(t, e, team, 1, "pm_card_visa")
	afterTenDays(e)

	got := change(t, e, sub, subscriptions.UpdateInput{PlanID: &pro.ID})
	if got.PlanID != pro.ID || got.Quantity != 1 || got.Status != store.Active || got.PendingPlanID != nil || got.PendingQuantity != nil {
		t.Fatalf("upgraded = %+v", got)
	}
	if !got.CurrentPeriodStart.Equal(sub.CurrentPeriodStart) || !got.CurrentPeriodEnd.Equal(sub.CurrentPeriodEnd) {
		t.Fatalf("the period moved: %+v", got)
	}
	// 21 of the period's 31 days remain: 2000 × 21/31 = 1354.84 is credited, 5000 × 21/31 = 3387.10 is charged.
	invs := invoicesOf(e, sub)
	if len(invs) != 2 {
		t.Fatalf("invoices = %+v, want the first period's and the proration", invs)
	}
	inv := invs[1]
	if want := []store.Line{{Description: "Unused time on Team", Quantity: 1, UnitAmount: -1355}, {Description: "Remaining time on Pro", Quantity: 1, UnitAmount: 3387}}; !reflect.DeepEqual(inv.Lines, want) {
		t.Fatalf("lines = %+v", inv.Lines)
	}
	if inv.Status != store.InvoicePaid || billing.Compute(inv).Total != 2032 || inv.PeriodStart == nil || !inv.PeriodStart.Equal(sub.CurrentPeriodStart) {
		t.Fatalf("proration invoice = %+v", inv)
	}
	if cs := e.Gateway.Charges(); len(cs) != 2 || cs[1].Amount != 2032 || cs[1].PaymentMethod != "pm_card_visa" {
		t.Fatalf("charges = %+v", cs)
	}
}

func TestUpgradeAppliesTheDiscountAndTax(t *testing.T) {
	e := apitest.New(t)
	if _, err := e.Store.UpdateOrg(e.Acme.ID, func(o *store.Org) error { o.TaxRateBP = 2000; return nil }); err != nil {
		t.Fatal(err)
	}
	team := newPlan(t, e, "Team", money.USD, 2000, store.Monthly, store.Licensed, 0)
	pro := newPlan(t, e, "Pro", money.USD, 5000, store.Monthly, store.Licensed, 0)
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	sub, err := e.Subs.Create(context.Background(), e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: team.ID, Quantity: 1, DiscountPercent: 10})
	if err != nil {
		t.Fatal(err)
	}
	afterTenDays(e)
	change(t, e, sub, subscriptions.UpdateInput{PlanID: &pro.ID})
	// The lines net to 2032 (not paid here: no payment method). The 10% discount is 203.2, rounded to 203; the 20% tax on
	// 1829 is 365.8, rounded to 366.
	inv := invoicesOf(e, sub)[1]
	if got := billing.Compute(inv); got != (billing.Totals{Subtotal: 2032, Discount: 203, Tax: 366, Total: 2195}) {
		t.Fatalf("totals = %+v", got)
	}
	if inv.DiscountPercent != 10 || inv.TaxRateBP != 2000 || inv.Status != store.InvoiceOpen {
		t.Fatalf("invoice = %+v", inv)
	}
}

func TestUpgradeWithoutPaymentMethodStaysOpen(t *testing.T) {
	e := apitest.New(t)
	team := newPlan(t, e, "Team", money.USD, 2000, store.Monthly, store.Licensed, 0)
	pro := newPlan(t, e, "Pro", money.USD, 5000, store.Monthly, store.Licensed, 0)
	sub := subscribe(t, e, team, 1, "")
	afterTenDays(e)
	got := change(t, e, sub, subscriptions.UpdateInput{PlanID: &pro.ID})
	if got.Status != store.Active || got.PlanID != pro.ID {
		t.Fatalf("upgraded = %+v", got)
	}
	if inv := invoicesOf(e, sub)[1]; inv.Status != store.InvoiceOpen || billing.Compute(inv).Total != 2032 {
		t.Fatalf("invoice = %+v", inv)
	}
	if n := len(e.Gateway.Charges()); n != 0 {
		t.Fatalf("%d charges without a payment method", n)
	}
}

func TestDeclinedUpgradeIsPastDue(t *testing.T) {
	e := apitest.New(t)
	team := newPlan(t, e, "Team", money.USD, 2000, store.Monthly, store.Licensed, 0)
	pro := newPlan(t, e, "Pro", money.USD, 5000, store.Monthly, store.Licensed, 0)
	sub := subscribe(t, e, team, 1, "pm_card_visa")
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, sub.CustomerID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_card_declined"; return nil })
	afterTenDays(e)
	got := change(t, e, sub, subscriptions.UpdateInput{PlanID: &pro.ID})
	if got.PlanID != pro.ID || got.Status != store.PastDue {
		t.Fatalf("declined upgrade = %+v, want the change applied and the subscription past due", got)
	}
	if inv := invoicesOf(e, sub)[1]; inv.Status != store.InvoiceOpen {
		t.Fatalf("invoice = %+v", inv)
	}
	if n := len(e.Payments.Pay); n != 0 {
		t.Fatal("unreachable")
	}
}

func TestUpgradeWhenGatewayIsDownKeepsTheChange(t *testing.T) {
	e := apitest.New(t)
	team := newPlan(t, e, "Team", money.USD, 2000, store.Monthly, store.Licensed, 0)
	pro := newPlan(t, e, "Pro", money.USD, 5000, store.Monthly, store.Licensed, 0)
	sub := subscribe(t, e, team, 1, "pm_card_visa")
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, sub.CustomerID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_gateway_down"; return nil })
	afterTenDays(e)
	got, err := e.Subs.Update(context.Background(), e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &pro.ID})
	if !errors.Is(err, payments.ErrUnavailable) || got.PlanID != pro.ID || got.Status != store.Active {
		t.Fatalf("update = %+v, %v", got, err)
	}
	if inv := invoicesOf(e, sub)[1]; inv.Status != store.InvoiceOpen {
		t.Fatalf("invoice = %+v", inv)
	}
}

func TestDowngradeTakesEffectAtRenewal(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	team := newPlan(t, e, "Team", money.USD, 2000, store.Monthly, store.Licensed, 0)
	pro := newPlan(t, e, "Pro", money.USD, 5000, store.Monthly, store.Licensed, 0)
	sub := subscribe(t, e, pro, 1, "pm_card_visa")
	afterTenDays(e)

	got := change(t, e, sub, subscriptions.UpdateInput{PlanID: &team.ID})
	if got.PlanID != pro.ID || got.Quantity != 1 || got.PendingPlanID == nil || *got.PendingPlanID != team.ID ||
		got.PendingQuantity == nil || *got.PendingQuantity != 1 {
		t.Fatalf("downgraded = %+v, want Pro still in effect and Team pending", got)
	}
	if n := len(invoicesOf(e, sub)); n != 1 {
		t.Fatalf("a downgrade billed: %d invoices", n)
	}
	if n := len(e.Gateway.Charges()); n != 1 {
		t.Fatalf("a downgrade charged: %d charges", n)
	}

	e.Clock.Set(got.CurrentPeriodEnd)
	if n, err := e.Subs.RenewDue(ctx); err != nil || n != 1 {
		t.Fatalf("RenewDue = %d, %v", n, err)
	}
	renewed, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
	if renewed.PlanID != team.ID || renewed.Quantity != 1 || renewed.PendingPlanID != nil || renewed.PendingQuantity != nil || renewed.Status != store.Active {
		t.Fatalf("renewed = %+v", renewed)
	}
	invs := invoicesOf(e, sub)
	if len(invs) != 2 || len(invs[1].Lines) != 1 || invs[1].Lines[0].UnitAmount != 2000 || invs[1].Lines[0].Quantity != 1 {
		t.Fatalf("renewal invoice = %+v", invs)
	}
	if cs := e.Gateway.Charges(); len(cs) != 2 || cs[1].Amount != 2000 {
		t.Fatalf("charges = %+v", cs)
	}
}

func TestPendingChangeIsClearedByPatchBackOrAnUpgrade(t *testing.T) {
	e := apitest.New(t)
	pro := newPlan(t, e, "Pro", money.USD, 5000, store.Monthly, store.Licensed, 0)
	sub := subscribe(t, e, pro, 3, "pm_card_visa")
	afterTenDays(e)
	one, three, four := 1, 3, 4

	got := change(t, e, sub, subscriptions.UpdateInput{Quantity: &one})
	if got.PendingQuantity == nil || *got.PendingQuantity != 1 || got.Quantity != 3 {
		t.Fatalf("downgraded = %+v", got)
	}
	got = change(t, e, sub, subscriptions.UpdateInput{Quantity: &three})
	if got.PendingPlanID != nil || got.PendingQuantity != nil || got.Quantity != 3 {
		t.Fatalf("back to the current quantity = %+v, want nothing pending", got)
	}
	if n := len(invoicesOf(e, sub)); n != 1 {
		t.Fatalf("returning to the current quantity billed: %d invoices", n)
	}

	change(t, e, sub, subscriptions.UpdateInput{Quantity: &one})
	got = change(t, e, sub, subscriptions.UpdateInput{Quantity: &four})
	if got.PendingPlanID != nil || got.PendingQuantity != nil || got.Quantity != 4 {
		t.Fatalf("upgraded = %+v, want the pending downgrade cleared", got)
	}
	if n := len(invoicesOf(e, sub)); n != 2 {
		t.Fatalf("upgrade invoices = %d", n)
	}
}

func TestPartialChangeKeepsThePendingPlan(t *testing.T) {
	e := apitest.New(t)
	team := newPlan(t, e, "Team", money.USD, 2000, store.Monthly, store.Licensed, 0)
	pro := newPlan(t, e, "Pro", money.USD, 5000, store.Monthly, store.Licensed, 0)
	sub := subscribe(t, e, pro, 3, "pm_card_visa")
	two := 2
	got := change(t, e, sub, subscriptions.UpdateInput{PlanID: &team.ID})
	if got.PendingPlanID == nil || *got.PendingPlanID != team.ID {
		t.Fatalf("downgraded = %+v", got)
	}
	// Team is 2000 × 2 = 4000 in the pending change; the quantity alone changes it, not the plan.
	got = change(t, e, sub, subscriptions.UpdateInput{Quantity: &two})
	if got.PlanID != pro.ID || got.PendingPlanID == nil || *got.PendingPlanID != team.ID || *got.PendingQuantity != 2 {
		t.Fatalf("after a quantity change = %+v, want Team still pending at quantity 2", got)
	}
}

func TestSameValueChangeAppliesAtOnceAndBillsNothing(t *testing.T) {
	e := apitest.New(t)
	team := newPlan(t, e, "Team", money.USD, 2000, store.Monthly, store.Licensed, 0)
	duo := newPlan(t, e, "Duo", money.USD, 4000, store.Monthly, store.Licensed, 0)
	sub := subscribe(t, e, team, 2, "pm_card_visa")
	afterTenDays(e)
	one := 1
	got := change(t, e, sub, subscriptions.UpdateInput{PlanID: &duo.ID, Quantity: &one})
	if got.PlanID != duo.ID || got.Quantity != 1 || got.PendingPlanID != nil {
		t.Fatalf("changed = %+v", got)
	}
	if n := len(invoicesOf(e, sub)); n != 1 || len(e.Gateway.Charges()) != 1 {
		t.Fatalf("an equal-value change billed: %d invoices, %d charges", n, len(e.Gateway.Charges()))
	}
}

func TestTrialingChangesAreNotBilled(t *testing.T) {
	e := apitest.New(t)
	trial := newPlan(t, e, "Trial", money.EUR, 4900, store.Monthly, store.Licensed, 14)
	pro := newPlan(t, e, "Pro", money.EUR, 9900, store.Monthly, store.Licensed, 0)
	starter := newPlan(t, e, "Starter", money.EUR, 900, store.Monthly, store.Licensed, 0)
	sub := subscribe(t, e, trial, 1, "pm_card_visa")
	if sub.Status != store.Trialing {
		t.Fatalf("subscription = %+v", sub)
	}
	got := change(t, e, sub, subscriptions.UpdateInput{PlanID: &pro.ID})
	if got.PlanID != pro.ID || got.Status != store.Trialing || got.PendingPlanID != nil {
		t.Fatalf("upgraded while trialing = %+v", got)
	}
	got = change(t, e, sub, subscriptions.UpdateInput{PlanID: &starter.ID})
	if got.PlanID != starter.ID || got.Status != store.Trialing || got.PendingPlanID != nil {
		t.Fatalf("downgraded while trialing = %+v, want it applied at once", got)
	}
	if n := len(invoicesOf(e, sub)); n != 0 {
		t.Fatalf("a trialing change was invoiced: %d", n)
	}
}

func TestIncompatiblePlansAreRefused(t *testing.T) {
	e := apitest.New(t)
	team := newPlan(t, e, "Team", money.USD, 2000, store.Monthly, store.Licensed, 0)
	sub := subscribe(t, e, team, 1, "pm_card_visa")
	eur := newPlan(t, e, "EUR", money.EUR, 9900, store.Monthly, store.Licensed, 0)
	yearly := newPlan(t, e, "Yearly", money.USD, 90000, store.Yearly, store.Licensed, 0)
	metered := newPlan(t, e, "Metered", money.USD, 2, store.Monthly, store.Metered, 0)
	for _, p := range []store.Plan{eur, yearly, metered} {
		_, err := e.Subs.Update(context.Background(), e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &p.ID})
		if !errors.Is(err, subscriptions.ErrIncompatiblePlan) {
			t.Fatalf("change to %s: err = %v", p.Name, err)
		}
	}
	if got, _ := e.Store.Subscription(e.Acme.ID, sub.ID); got.PlanID != team.ID {
		t.Fatalf("a refused change applied: %+v", got)
	}
	// A metered plan is never compatible, even with itself: its usage is what is billed.
	meteredSub := subscribe(t, e, metered, 1, "pm_card_visa")
	two := 2
	if _, err := e.Subs.Update(context.Background(), e.Acme.ID, meteredSub.ID, subscriptions.UpdateInput{Quantity: &two}); !errors.Is(err, subscriptions.ErrIncompatiblePlan) {
		t.Fatalf("quantity of a metered subscription: err = %v", err)
	}
}

func TestCancelClearsThePendingChange(t *testing.T) {
	e := apitest.New(t)
	team := newPlan(t, e, "Team", money.USD, 2000, store.Monthly, store.Licensed, 0)
	pro := newPlan(t, e, "Pro", money.USD, 5000, store.Monthly, store.Licensed, 0)
	sub := subscribe(t, e, pro, 1, "pm_card_visa")
	change(t, e, sub, subscriptions.UpdateInput{PlanID: &team.ID})
	got, err := e.Subs.Cancel(context.Background(), e.Acme.ID, sub.ID, false)
	if err != nil || got.Status != store.Canceled || got.PendingPlanID != nil || got.PendingQuantity != nil {
		t.Fatalf("cancel = %+v, %v", got, err)
	}
}

