+// subscribe starts a monthly subscription of Acme's customer Jane to plan p, paid by payment method pm.
+func subscribe(t *testing.T, e *apitest.Env, p store.Plan, qty int, pm string) store.Subscription {
+	t.Helper()
+	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
