+// change applies an update to a subscription of Acme's.
+func change(t *testing.T, e *apitest.Env, sub store.Subscription, in subscriptions.UpdateInput) store.Subscription {
+	t.Helper()
+	got, err := e.Subs.Update(context.Background(), e.Acme.ID, sub.ID, in)
+	if err != nil {
