func TestDowngradeTakesEffectAtRenewal(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	team := newPlan(t, e, "Team", money.USD, 2000, store.Monthly, store.Licensed, 0)
	pro := newPlan(t, e, "Pro", money.USD, 5000, store.Monthly, store.Licensed, 0)
	sub := subscribe(t, e, pro, 1, "pm_card_visa")
	afterTenDays(e)

	got := change(t, e, sub, subscriptions.UpdateInput{PlanID: &team.ID})
	if got.PlanID != pro.ID || got.Quantity != 1 || got.PendingPlanID == nil || *got.PendingPlanID != team.ID ||
		got.PendingQuantity == nil || *got.PendingQuantity != 1 {
		t.Fatalf("downgraded = %+v, want Pro still in effect and Team pending", got)
	}
	if n := len(invoicesOf(e, sub)); n != 1 {
		t.Fatalf("a downgrade billed: %d invoices", n)
	}
	if n := len(e.Gateway.Charges()); n != 1 {
		t.Fatalf("a downgrade charged: %d charges", n)
	}

	e.Clock.Set(got.CurrentPeriodEnd)
	if n, err := e.Subs.RenewDue(ctx); err != nil || n != 1 {
		t.Fatalf("RenewDue = %d, %v", n, err)
	}
	renewed, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
	if renewed.PlanID != team.ID || renewed.Quantity != 1 || renewed.PendingPlanID != nil || renewed.PendingQuantity != nil || renewed.Status != store.Active {
		t.Fatalf("renewed = %+v", renewed)
	}
	invs := invoicesOf(e, sub)
	if len(invs) != 2 || len(invs[1].Lines) != 1 || invs[1].Lines[0].UnitAmount != 2000 || invs[1].Lines[0].Quantity != 1 {
		t.Fatalf("renewal invoice = %+v", invs)
	}
	if cs := e.Gateway.Charges(); len(cs) != 2 || cs[1].Amount != 2000 {
		t.Fatalf("charges = %+v", cs)
	}
}

func TestPendingChangeIsClearedByPatchBackOrAnUpgrade(t *testing.T) {
	e := apitest.New(t)
	pro := newPlan(t, e, "Pro", money.USD, 5000, store.Monthly, store.Licensed, 0)
	sub := subscribe(t, e, pro, 3, "pm_card_visa")
	afterTenDays(e)
	one, three, four := 1, 3, 4

	got := change(t, e, sub, subscriptions.UpdateInput{Quantity: &one})
	if got.PendingQuantity == nil || *got.PendingQuantity != 1 || got.Quantity != 3 {
		t.Fatalf("downgraded = %+v", got)
	}
	got = change(t, e, sub, subscriptions.UpdateInput{Quantity: &three})
	if got.PendingPlanID != nil || got.PendingQuantity != nil || got.Quantity != 3 {
		t.Fatalf("back to the current quantity = %+v, want nothing pending", got)
	}
	if n := len(invoicesOf(e, sub)); n != 1 {
		t.Fatalf("returning to the current quantity billed: %d invoices", n)
	}

	change(t, e, sub, subscriptions.UpdateInput{Quantity: &one})
	got = change(t, e, sub, subscriptions.UpdateInput{Quantity: &four})
	if got.PendingPlanID != nil || got.PendingQuantity != nil || got.Quantity != 4 {
		t.Fatalf("upgraded = %+v, want the pending downgrade cleared", got)
	}
	if n := len(invoicesOf(e, sub)); n != 2 {
		t.Fatalf("upgrade invoices = %d", n)
	}
}

func TestPartialChangeKeepsThePendingPlan(t *testing.T) {
	e := apitest.New(t)
	team := newPlan(t, e, "Team", money.USD, 2000, store.Monthly, store.Licensed, 0)
	pro := newPlan(t, e, "Pro", money.USD, 5000, store.Monthly, store.Licensed, 0)
	sub := subscribe(t, e, pro, 3, "pm_card_visa")
	two := 2
	got := change(t, e, sub, subscriptions.UpdateInput{PlanID: &team.ID})
	if got.PendingPlanID == nil || *got.PendingPlanID != team.ID {
		t.Fatalf("downgraded = %+v", got)
	}
	// Team is 2000 × 2 = 4000 in the pending change; the quantity alone changes it, not the plan.
	got = change(t, e, sub, subscriptions.UpdateInput{Quantity: &two})
	if got.PlanID != pro.ID || got.PendingPlanID == nil || *got.PendingPlanID != team.ID || *got.PendingQuantity != 2 {
		t.Fatalf("after a quantity change = %+v, want Team still pending at quantity 2", got)
	}
}

func TestSameValueChangeAppliesAtOnceAndBillsNothing(t *testing.T) {
	e := apitest.New(t)
	team := newPlan(t, e, "Team", money.USD, 2000, store.Monthly, store.Licensed, 0)
	duo := newPlan(t, e, "Duo", money.USD, 4000, store.Monthly, store.Licensed, 0)
	sub := subscribe(t, e, team, 2, "pm_card_visa")
	afterTenDays(e)
	one := 1
	got := change(t, e, sub, subscriptions.UpdateInput{PlanID: &duo.ID, Quantity: &one})
	if got.PlanID != duo.ID || got.Quantity != 1 || got.PendingPlanID != nil {
		t.Fatalf("changed = %+v", got)
	}
	if n := len(invoicesOf(e, sub)); n != 1 || len(e.Gateway.Charges()) != 1 {
		t.Fatalf("an equal-value change billed: %d invoices, %d charges", n, len(e.Gateway.Charges()))
	}
}

func TestTrialingChangesAreNotBilled(t *testing.T) {
	e := apitest.New(t)
	trial := newPlan(t, e, "Trial", money.EUR, 4900, store.Monthly, store.Licensed, 14)
	pro := newPlan(t, e, "Pro", money.EUR, 9900, store.Monthly, store.Licensed, 0)
	starter := newPlan(t, e, "Starter", money.EUR, 900, store.Monthly, store.Licensed, 0)
	sub := subscribe(t, e, trial, 1, "pm_card_visa")
	if sub.Status != store.Trialing {
		t.Fatalf("subscription = %+v", sub)
	}
	got := change(t, e, sub, subscriptions.UpdateInput{PlanID: &pro.ID})
	if got.PlanID != pro.ID || got.Status != store.Trialing || got.PendingPlanID != nil {
		t.Fatalf("upgraded while trialing = %+v", got)
	}
	got = change(t, e, sub, subscriptions.UpdateInput{PlanID: &starter.ID})
	if got.PlanID != starter.ID || got.Status != store.Trialing || got.PendingPlanID != nil {
		t.Fatalf("downgraded while trialing = %+v, want it applied at once", got)
	}
	if n := len(invoicesOf(e, sub)); n != 0 {
		t.Fatalf("a trialing change was invoiced: %d", n)
	}
}

func TestIncompatiblePlansAreRefused(t *testing.T) {
	e := apitest.New(t)
	team := newPlan(t, e, "Team", money.USD, 2000, store.Monthly, store.Licensed, 0)
	sub := subscribe(t, e, team, 1, "pm_card_visa")
	eur := newPlan(t, e, "EUR", money.EUR, 9900, store.Monthly, store.Licensed, 0)
	yearly := newPlan(t, e, "Yearly", money.USD, 90000, store.Yearly, store.Licensed, 0)
	metered := newPlan(t, e, "Metered", money.USD, 2, store.Monthly, store.Metered, 0)
	for _, p := range []store.Plan{eur, yearly, metered} {
		_, err := e.Subs.Update(context.Background(), e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &p.ID})
		if !errors.Is(err, subscriptions.ErrIncompatiblePlan) {
			t.Fatalf("change to %s: err = %v", p.Name, err)
		}
	}
	if got, _ := e.Store.Subscription(e.Acme.ID, sub.ID); got.PlanID != team.ID {
		t.Fatalf("a refused change applied: %+v", got)
	}
	// A metered plan is never compatible, even with itself: its usage is what is billed.
	meteredSub := subscribe(t, e, metered, 1, "pm_card_visa")
	two := 2
	if _, err := e.Subs.Update(context.Background(), e.Acme.ID, meteredSub.ID, subscriptions.UpdateInput{Quantity: &two}); !errors.Is(err, subscriptions.ErrIncompatiblePlan) {
		t.Fatalf("quantity of a metered subscription: err = %v", err)
	}
}

func TestCancelClearsThePendingChange(t *testing.T) {
	e := apitest.New(t)
	team := newPlan(t, e, "Team", money.USD, 2000, store.Monthly, store.Licensed, 0)
	pro := newPlan(t, e, "Pro", money.USD, 5000, store.Monthly, store.Licensed, 0)
	sub := subscribe(t, e, pro, 1, "pm_card_visa")
	change(t, e, sub, subscriptions.UpdateInput{PlanID: &team.ID})
	got, err := e.Subs.Cancel(context.Background(), e.Acme.ID, sub.ID, false)
	if err != nil || got.Status != store.Canceled || got.PendingPlanID != nil || got.PendingQuantity != nil {
		t.Fatalf("cancel = %+v, %v", got, err)
	}
}

