func TestSubscriptionPlanChangesOverHTTP(t *testing.T) {
	e := apitest.New(t)
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	team := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	pro := e.CreatePlan(e.Acme, "Pro", "USD", "50.00")
	var yearly, eur store.Plan
	e.MustDo(http.StatusCreated, "POST", "/v1/plans", e.Acme.Key, map[string]any{"name": "Yearly", "currency": "USD", "price": "200.00", "interval": "year"}, &yearly)
	e.MustDo(http.StatusCreated, "POST", "/v1/plans", e.Acme.Key, map[string]any{"name": "Team EUR", "currency": "EUR", "price": "20.00", "interval": "month"}, &eur)

	var sub store.Subscription
	r := e.MustDo(http.StatusCreated, "POST", "/v1/subscriptions", e.Acme.Key, map[string]any{"customer_id": c.ID, "plan_id": team.ID, "quantity": 2}, &sub)
	if m := r.Map(t); m["pending_plan_id"] != nil || m["pending_quantity"] != nil {
		t.Fatalf("a new subscription has a pending change: %s", r)
	}

	// Team × 2 is 4000; Pro × 2 is 10000: an upgrade, billed at once (no payment method, so the invoice stays open).
	e.MustDo(http.StatusOK, "PATCH", "/v1/subscriptions/"+sub.ID, e.Acme.Key, map[string]any{"plan_id": pro.ID}, &sub)
	if sub.PlanID != pro.ID || sub.Quantity != 2 || sub.PendingPlanID != nil {
		t.Fatalf("upgraded = %+v", sub)
	}
	var invs struct{ Items []store.Invoice }
	e.MustDo(http.StatusOK, "GET", "/v1/invoices?customer_id="+c.ID, e.Acme.Key, nil, &invs)
	if len(invs.Items) != 2 || invs.Items[1].Status != store.InvoiceOpen || len(invs.Items[1].Lines) != 2 {
		t.Fatalf("invoices = %+v", invs.Items)
	}

	// Pro × 1 is 5000: a downgrade, pending until the next renewal.
	var down store.Subscription
	e.MustDo(http.StatusOK, "PATCH", "/v1/subscriptions/"+sub.ID, e.Acme.Key, map[string]any{"quantity": 1}, &down)
	if down.PlanID != pro.ID || down.Quantity != 2 || down.PendingPlanID == nil || *down.PendingPlanID != pro.ID || down.PendingQuantity == nil || *down.PendingQuantity != 1 {
		t.Fatalf("downgraded = %+v", down)
	}

	for _, bad := range []string{yearly.ID, eur.ID} {
		if r := e.Do("PATCH", "/v1/subscriptions/"+sub.ID, e.Acme.Key, map[string]any{"plan_id": bad}); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "incompatible_plan" {
			t.Fatalf("change to plan %s: %s", bad, r)
		}
	}

	// Back to the current quantity clears the pending downgrade.
	var back store.Subscription
	e.MustDo(http.StatusOK, "PATCH", "/v1/subscriptions/"+sub.ID, e.Acme.Key, map[string]any{"quantity": 2}, &back)
	if back.PendingPlanID != nil || back.PendingQuantity != nil || back.Quantity != 2 {
		t.Fatalf("back = %+v", back)
	}
}
EOF
